/**
 * Public comments + reactions for a parent resource (project or bulletin).
 * Visitors don't log in: comments carry a display name, and reactions carry a
 * visitor_id (a random ID generated by the frontend) so each visitor gets one reaction per item.
 */
const { supabaseAdmin } = require('../config/supabase');
const { REACTION_TYPES } = require('../config/constants');
const ApiError = require('../utils/ApiError');
const asyncHandler = require('../utils/asyncHandler');
const dbError = require('../utils/dbError');
const validators = require('../utils/validators');
const { parsePagination, buildMeta, fetchPage } = require('../utils/pagination');
const engagement = require('../services/engagement');

const COMMENT_FIELDS = 'id,author_name,body,created_at';

module.exports = function createEngagementController({ targetType, table, label }) {
  const assertTarget = async (id) => {
    if (!validators.isUuid(id)) throw new ApiError(400, 'Invalid id: must be a UUID');
    const { data, error } = await supabaseAdmin.from(table).select('id').eq('id', id).maybeSingle();
    if (error) throw dbError(error);
    if (!data) throw new ApiError(404, `${label} not found`);
  };

  const listComments = asyncHandler(async (req, res) => {
    await assertTarget(req.params.id);
    const { page, limit, from, to } = parsePagination(req.query, { defaultLimit: 20 });

    const build = () =>
      supabaseAdmin
        .from('comments')
        .select(COMMENT_FIELDS, { count: 'exact' })
        .eq('target_type', targetType)
        .eq('target_id', req.params.id)
        .order('created_at', { ascending: false });

    const { data, count } = await fetchPage(build, from, to);
    res.json({ success: true, data, meta: buildMeta(page, limit, count) });
  });

  const addComment = asyncHandler(async (req, res) => {
    await assertTarget(req.params.id);
    const body = req.body || {};
    const errors = {};
    let author_name;
    let text;

    try { author_name = validators.text({ min: 1, max: 80 })(body.author_name); } catch (e) { errors.author_name = e.message; }
    try { text = validators.text({ min: 1, max: 1000 })(body.body); } catch (e) { errors.body = e.message; }
    if (Object.keys(errors).length) throw new ApiError(400, 'Validation failed', errors);

    const { data, error } = await supabaseAdmin
      .from('comments')
      .insert({ target_type: targetType, target_id: req.params.id, author_name, body: text })
      .select(COMMENT_FIELDS)
      .single();
    if (error) throw dbError(error);

    res.status(201).json({ success: true, data });
  });

  const reactionState = async (id, visitorId) => {
    const summary = (await engagement.getSummaries(targetType, [id])).get(id);
    let mine = null;
    if (visitorId) {
      const { data, error } = await supabaseAdmin
        .from('reactions')
        .select('type')
        .eq('target_type', targetType)
        .eq('target_id', id)
        .eq('visitor_id', visitorId)
        .maybeSingle();
      if (error) throw dbError(error);
      mine = data ? data.type : null;
    }
    return { reactions: summary.reactions, reactions_total: summary.reactions_total, my_reaction: mine };
  };

  const getReactions = asyncHandler(async (req, res) => {
    await assertTarget(req.params.id);
    const visitorId = req.query.visitor_id;
    if (visitorId !== undefined && !validators.isVisitorId(visitorId)) {
      throw new ApiError(400, 'visitor_id must be 8-100 characters: letters, numbers, - or _');
    }
    res.json({ success: true, data: await reactionState(req.params.id, visitorId) });
  });

  // Toggle: same type again removes it, a different type switches it, none adds it.
  const toggleReaction = asyncHandler(async (req, res) => {
    await assertTarget(req.params.id);
    const { type, visitor_id: visitorId } = req.body || {};
    const errors = {};
    if (!REACTION_TYPES.includes(type)) errors.type = `must be one of: ${REACTION_TYPES.join(', ')}`;
    if (!validators.isVisitorId(visitorId)) {
      errors.visitor_id = 'must be 8-100 characters: letters, numbers, - or _';
    }
    if (Object.keys(errors).length) throw new ApiError(400, 'Validation failed', errors);

    const id = req.params.id;
    const { data: existing, error: findError } = await supabaseAdmin
      .from('reactions')
      .select('id,type')
      .eq('target_type', targetType)
      .eq('target_id', id)
      .eq('visitor_id', visitorId)
      .maybeSingle();
    if (findError) throw dbError(findError);

    let action;
    if (!existing) {
      const { error } = await supabaseAdmin
        .from('reactions')
        .insert({ target_type: targetType, target_id: id, visitor_id: visitorId, type });
      // 23505 = a double-click raced us; the reaction already exists, which is fine.
      if (error && error.code !== '23505') throw dbError(error);
      action = 'added';
    } else if (existing.type === type) {
      const { error } = await supabaseAdmin.from('reactions').delete().eq('id', existing.id);
      if (error) throw dbError(error);
      action = 'removed';
    } else {
      const { error } = await supabaseAdmin.from('reactions').update({ type }).eq('id', existing.id);
      if (error) throw dbError(error);
      action = 'changed';
    }

    res.json({ success: true, data: { action, ...(await reactionState(id, visitorId)) } });
  });

  return { listComments, addComment, getReactions, toggleReaction };
};
